    #[test]
    fn relay_container_operation_admission_is_owner_and_deadline_fenced() {
        let record = relay_container_test_record();
        let mut reservation = relay_billing_test_reservation("reserved");
        reservation.lease_expires_at = record.owner_lease_expires_at;
        reservation.owner_deadline_at = record.owner_lease_expires_at;
        assert_eq!(
            classify_relay_container_operation_reservation(&reservation, &record),
            None
        );

        reservation.status = "settled".to_string();
        assert_eq!(
            classify_relay_container_operation_reservation(&reservation, &record),
            Some(RelayContainerOperationWriteOutcome::ReservationNotReserved)
        );
        reservation.status = "reserved".to_string();
        reservation.owner_generation = 3;
        assert_eq!(
            classify_relay_container_operation_reservation(&reservation, &record),
            Some(RelayContainerOperationWriteOutcome::StaleGeneration)
        );
        reservation.owner_generation = record.owner_generation;
        reservation.channel_id = 8;
        assert_eq!(
            classify_relay_container_operation_reservation(&reservation, &record),
            Some(RelayContainerOperationWriteOutcome::SelectedAttemptConflict)
        );
        reservation.channel_id = record.channel_id;
        reservation.owner_deadline_at = record.execution_deadline_at - 1;
        assert_eq!(
            classify_relay_container_operation_reservation(&reservation, &record),
            Some(RelayContainerOperationWriteOutcome::DeadlineExpired)
        );
        reservation.owner_deadline_at = record.owner_lease_expires_at;
        reservation.lease_expires_at = record.owner_lease_expires_at + 1;
        assert_eq!(
            classify_relay_container_operation_reservation(&reservation, &record),
            Some(RelayContainerOperationWriteOutcome::Conflict)
        );
    }

    #[test]
    fn relay_container_operation_retries_match_immutable_identity_after_dispatch() {
        let record = relay_container_test_record();
        let mut operation = relay_container_test_operation();
        assert!(relay_container_operation_matches_record(
            &operation, &record
        ));

        operation.status = "completed".to_string();
        operation.response_status = Some(200);
        operation.result_object_key =
            Some("container-results/v1/op_test_001/result.json".to_string());
        operation.result_object_version = Some("version-result-001".to_string());
        operation.result_sha256 =
            Some("cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc".to_string());
        operation.result_size = Some(256);
        operation.result_content_type = Some("application/json".to_string());
        operation.updated_at += 1;
        assert!(relay_container_operation_matches_record(
            &operation, &record
        ));

        operation.trace_id = "trace-forged".to_string();
        assert!(!relay_container_operation_matches_record(
            &operation, &record
        ));
    }

    #[test]
    fn relay_container_operation_dispatch_classification_is_generation_and_deadline_fenced() {
        let record = relay_container_test_record();
        let mut operation = relay_container_test_operation();
        let mut reservation = relay_billing_test_reservation("reserved");
        reservation.lease_expires_at = record.owner_lease_expires_at;
        reservation.owner_deadline_at = record.owner_lease_expires_at;
        assert_eq!(
            classify_relay_container_dispatch(
                &operation,
                Some(&reservation),
                record.operation_id,
                record.owner_generation,
                record.admission_sha256,
                100,
            ),
            None
        );

        operation.status = "dispatched".to_string();
        operation.updated_at = 100;
        assert_eq!(
            classify_relay_container_dispatch(
                &operation,
                Some(&reservation),
                record.operation_id,
                record.owner_generation,
                record.admission_sha256,
                100,
            ),
            Some(RelayContainerOperationDispatchOutcome::AlreadyDispatched)
        );

        operation.status = "prepared".to_string();
        assert_eq!(
            classify_relay_container_dispatch(
                &operation,
                Some(&reservation),
                record.operation_id,
                record.owner_generation,
                record.admission_sha256,
                record.execution_deadline_at,
            ),
            Some(RelayContainerOperationDispatchOutcome::DeadlineExpired)
        );
        reservation.status = "settled".to_string();
        assert_eq!(
            classify_relay_container_dispatch(
                &operation,
                Some(&reservation),
                record.operation_id,
                record.owner_generation,
                record.admission_sha256,
                100,
            ),
            Some(RelayContainerOperationDispatchOutcome::ReservationNotReserved)
        );
    }

    #[test]
    fn relay_container_operation_terminal_contract_requires_exact_outcome_manifest() {
        let record = relay_container_test_record();
        let result = relay_container_test_result();
        let completed = RelayContainerOperationTerminalRecord::Completed {
            response_status: 200,
            result,
        };
        validate_relay_container_terminal_record(
            record.reservation_key,
            record.operation_id,
            record.owner_generation,
            record.admission_sha256,
            RelayContainerOperationExpectedStatus::Dispatched,
            completed,
            150,
        )
        .unwrap();
        assert!(validate_relay_container_terminal_record(
            record.reservation_key,
            record.operation_id,
            record.owner_generation,
            record.admission_sha256,
            RelayContainerOperationExpectedStatus::Prepared,
            completed,
            150,
        )
        .is_err());

        let invalid = RelayContainerOperationTerminalRecord::Completed {
            response_status: 202,
            result,
        };
        assert!(validate_relay_container_terminal_record(
            record.reservation_key,
            record.operation_id,
            record.owner_generation,
            record.admission_sha256,
            RelayContainerOperationExpectedStatus::Dispatched,
            invalid,
            150,
        )
        .is_err());

        let recovery = RelayContainerOperationTerminalRecord::RecoveryRequired {
            response_code: "container_execution_ambiguous",
            result: Some(result),
        };
        validate_relay_container_terminal_record(
            record.reservation_key,
            record.operation_id,
            record.owner_generation,
            record.admission_sha256,
            RelayContainerOperationExpectedStatus::Dispatched,
            recovery,
            181,
        )
        .unwrap();

        let failed = RelayContainerOperationTerminalRecord::Failed {
            response_status: 503,
            response_code: "container_not_dispatched",
        };
        validate_relay_container_terminal_record(
            record.reservation_key,
            record.operation_id,
            record.owner_generation,
            record.admission_sha256,
            RelayContainerOperationExpectedStatus::Prepared,
            failed,
            150,
        )
        .unwrap();
    }

    #[test]
    fn relay_container_operation_terminal_replay_is_exact_and_recovery_is_resolvable() {
        let record = relay_container_test_record();
        let result = relay_container_test_result();
        let terminal = RelayContainerOperationTerminalRecord::Completed {
            response_status: 200,
            result,
        };
        let mut operation = relay_container_test_operation();
        operation.status = "dispatched".to_string();
        operation.updated_at = 100;
        let mut reservation = relay_billing_test_reservation("reserved");
        reservation.lease_expires_at = record.owner_lease_expires_at;
        reservation.owner_generation = record.owner_generation;
        assert_eq!(
            classify_relay_container_terminal(
                &operation,
                Some(&reservation),
                record.operation_id,
                record.owner_generation,
                record.admission_sha256,
                RelayContainerOperationExpectedStatus::Dispatched,
                terminal,
                record.owner_lease_expires_at + 1,
            ),
            Some(RelayContainerOperationTerminalOutcome::LeaseExpired)
        );

        operation.status = "completed".to_string();
        operation.response_status = Some(200);
        operation.result_object_key = Some(result.object_key.to_string());
        operation.result_object_version = Some(result.object_version.to_string());
        operation.result_sha256 = Some(result.sha256.to_string());
        operation.result_size = Some(result.size);
        operation.result_content_type = Some(result.content_type.to_string());
        operation.updated_at = 150;
        reservation.status = "settled".to_string();
        assert_eq!(
            classify_relay_container_terminal(
                &operation,
                Some(&reservation),
                record.operation_id,
                record.owner_generation,
                record.admission_sha256,
                RelayContainerOperationExpectedStatus::Dispatched,
                terminal,
                160,
            ),
            Some(RelayContainerOperationTerminalOutcome::MatchingTerminal)
        );

        operation.result_object_version = Some("forged-version".to_string());
        assert_eq!(
            classify_relay_container_terminal(
                &operation,
                Some(&reservation),
                record.operation_id,
                record.owner_generation,
                record.admission_sha256,
                RelayContainerOperationExpectedStatus::Dispatched,
                terminal,
                160,
            ),
            Some(RelayContainerOperationTerminalOutcome::AlreadyTerminal)
        );

        operation = relay_container_test_operation();
        operation.status = "recovery_required".to_string();
        operation.response_status = Some(202);
        operation.response_code = Some("container_execution_ambiguous".to_string());
        operation.updated_at = 181;
        reservation.status = "reserved".to_string();
        reservation.owner_generation = record.owner_generation;
        assert_eq!(
            classify_relay_container_terminal(
                &operation,
                Some(&reservation),
                record.operation_id,
                record.owner_generation,
                record.admission_sha256,
                RelayContainerOperationExpectedStatus::RecoveryRequired,
                terminal,
                190,
            ),
            None
        );
    }

    #[test]
    fn relay_container_financial_settlement_freezes_every_quota_delta() {
        let headers = "{\"cache-control\":\"no-store\",\"content-type\":\"application/json\",\"x-request-id\":\"request-001\"}";
        let headers_sha256 = relay_container_sha256_hex(headers.as_bytes());
        let response_key = concat!(
            "container-client-responses/v1/relayreserve-test/2/",
            "9999999999999999999999999999999999999999999999999999999999999999"
        );
        let response = relay_container_test_client_response(200, &headers_sha256, response_key);
        let audit_payload = "{\"action\":\"container_terminal\",\"request_id\":\"request-001\"}";
        let audit_sha256 = relay_container_sha256_hex(audit_payload.as_bytes());
        let result = relay_container_test_result();
        let mut operation = relay_container_test_operation();
        operation.status = "dispatched".to_string();

        for (final_quota, expected_remain_delta) in [(150, -50), (100, 0), (60, 40)] {
            let mut reservation = relay_billing_test_reservation("reserved");
            reservation.pre_consumed_quota = 100;
            reservation.final_quota = 0;
            reservation.finalization_reason.clear();
            reservation.request_accounted = 0;
            reservation.lease_expires_at = operation.owner_lease_expires_at;
            let command = RelayContainerFinancialTerminalCommand {
                reservation_key: &operation.reservation_key,
                operation_id: &operation.operation_id,
                operation_owner_generation: operation.owner_generation,
                expected_operation_status: RelayContainerOperationExpectedStatus::Dispatched,
                admission_sha256: &operation.admission_sha256,
                billing_owner_generation: reservation.owner_generation,
                terminal: RelayContainerOperationTerminalRecord::Completed {
                    response_status: 200,
                    result,
                },
                action: RelayContainerFinancialTerminalAction::Settle {
                    final_quota,
                    finalization_reason: "container_usage_settlement",
                    provider_usage_receipt_sha256:
                        "dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd",
                    provider_result_sha256:
                        "cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc",
                    provider_attempt_generation: 1,
                },
                client_response: Some(response),
                provider_response: Some(relay_container_test_provider_response(
                    "succeeded",
                    "success",
                    200,
                    200,
                    None,
                    response,
                )),
                audit_payload_json: audit_payload,
                audit_payload_sha256: &audit_sha256,
                scheduled_terminalization: None,
                committed_at: 150,
            };
            let prepared =
                prepare_relay_container_financial_terminal(&command, &operation, &reservation)
                    .unwrap();
            assert_eq!(prepared.billing_action, "settle");
            assert_eq!(prepared.billing_final_quota, Some(final_quota));
            assert_eq!(prepared.user_quota_delta, expected_remain_delta);
            assert_eq!(prepared.token_quota_delta, expected_remain_delta);
            assert_eq!(prepared.user_used_quota_delta, final_quota);
            assert_eq!(prepared.channel_used_quota_delta, final_quota);
            assert_eq!(prepared.request_count_delta, 1);
            let receipt = relay_container_test_financial_receipt(&command, &operation, &prepared);
            assert!(relay_container_financial_receipt_integrity_valid(&receipt));
            assert_eq!(
                receipt.client_response_artifact_sha256.as_deref(),
                Some(response.artifact_sha256)
            );
            let replay_manifest =
                crate::container_reconciliation::client_response_manifest_from_receipt(&receipt)
                    .unwrap()
                    .unwrap();
            assert_eq!(replay_manifest.status, 200);
            assert_eq!(replay_manifest.body.object_key, response_key);
            assert_eq!(replay_manifest.body.size, 384);
            let mut tampered = receipt;
            tampered.client_response_artifact_sha256 = None;
            assert!(!relay_container_financial_receipt_integrity_valid(
                &tampered
            ));
            tampered.client_response_artifact_sha256 = Some(response.artifact_sha256.to_string());
            tampered.billing_current_reason = "tampered".to_string();
            assert!(!relay_container_financial_receipt_integrity_valid(
                &tampered
            ));
            assert!(
                crate::container_reconciliation::client_response_manifest_from_receipt(&tampered)
                    .is_err()
            );
        }
    }

    #[test]
    fn relay_container_provider_usage_quote_accepts_only_matching_preterminal_reservations() {
        let mut operation = relay_container_test_operation();
        let mut reservation = relay_billing_test_reservation("reserved");

        operation.status = "dispatched".to_string();
        assert!(relay_container_provider_usage_quote_reservation_matches(
            &operation,
            &reservation
        ));

        reservation.selected_group = "other".to_string();
        assert!(!relay_container_provider_usage_quote_reservation_matches(
            &operation,
            &reservation
        ));
        reservation.selected_group = operation.selected_group.clone();

        operation.status = "recovery_required".to_string();
        reservation.status = "recovery_required".to_string();
        reservation.owner_generation = operation.owner_generation + 1;
        assert!(relay_container_provider_usage_quote_reservation_matches(
            &operation,
            &reservation
        ));

        reservation.owner_generation = operation.owner_generation;
        assert!(!relay_container_provider_usage_quote_reservation_matches(
            &operation,
            &reservation
        ));

        operation.status = "prepared".to_string();
        reservation.status = "reserved".to_string();
        assert!(!relay_container_provider_usage_quote_reservation_matches(
            &operation,
            &reservation
        ));
    }

    #[test]
    fn relay_container_provider_usage_recomputes_tiered_quota_and_rejects_fallbacks() {
        let snapshot = cinatoken_billing::estimate_tiered_billing_snapshot_with_request_at(
            "gpt-test",
            r#"tier("default", p * 2 + c * 10)"#,
            cinatoken_billing::TokenParams {
                p: 100.0,
                c: 50.0,
                ..cinatoken_billing::TokenParams::default()
            },
            1.0,
            cinatoken_billing::RequestInput::default(),
            1_700_000_000,
        )
        .unwrap();
        let mut reservation = relay_billing_test_reservation("reserved");
        reservation.billing_kind = "tiered_expr".to_string();
        reservation.expr_hash = snapshot.expr_hash.clone();
        reservation.selected_group = "default".to_string();
        reservation.billing_snapshot_json =
            serde_json::to_string(&BTreeMap::from([("default".to_string(), snapshot)])).unwrap();

        let payload = relay_container_test_provider_usage_payload();
        assert_eq!(
            relay_container_provider_usage_final_quota(&payload, &reservation, None).unwrap(),
            3_500
        );

        let mut missing = payload.clone();
        missing.usage_present = false;
        missing.reported_usage_fields = 0;
        assert!(relay_container_provider_usage_final_quota(&missing, &reservation, None).is_err());

        let mut unversioned_tool_charge = payload;
        unversioned_tool_charge.responses_web_search_calls = 1;
        assert!(relay_container_provider_usage_final_quota(
            &unversioned_tool_charge,
            &reservation,
            None,
        )
        .is_err());

        let cache_snapshot = cinatoken_billing::estimate_tiered_billing_snapshot_with_request_at(
            "gpt-test",
            r#"tier("default", p * 2 + c * 10 + cr * 0.5)"#,
            cinatoken_billing::TokenParams {
                p: 100.0,
                c: 50.0,
                cr: 0.0,
                ..cinatoken_billing::TokenParams::default()
            },
            1.0,
            cinatoken_billing::RequestInput::default(),
            1_700_000_000,
        )
        .unwrap();
        reservation.expr_hash = cache_snapshot.expr_hash.clone();
        reservation.billing_snapshot_json =
            serde_json::to_string(&BTreeMap::from([("default".to_string(), cache_snapshot)]))
                .unwrap();
        let mut missing_cache_evidence = relay_container_test_provider_usage_payload();
        missing_cache_evidence.reported_usage_fields =
            RELAY_CONTAINER_USAGE_PROMPT_REPORTED | RELAY_CONTAINER_USAGE_COMPLETION_REPORTED;
        missing_cache_evidence.total_tokens = 0;
        assert!(relay_container_provider_usage_final_quota(
            &missing_cache_evidence,
            &reservation,
            None,
        )
        .is_err());
        missing_cache_evidence.reported_usage_fields |= RELAY_CONTAINER_USAGE_CACHED_REPORTED;
        assert_eq!(
            relay_container_provider_usage_final_quota(
                &missing_cache_evidence,
                &reservation,
                None,
            )
                .unwrap(),
            3_500
        );

        let cc1h_snapshot = cinatoken_billing::estimate_tiered_billing_snapshot_with_request_at(
            "gpt-test",
            r#"tier("default", p * 2 + c * 10 + cc1h * 6)"#,
            cinatoken_billing::TokenParams {
                p: 100.0,
                c: 50.0,
                ..cinatoken_billing::TokenParams::default()
            },
            1.0,
            cinatoken_billing::RequestInput::default(),
            1_700_000_000,
        )
        .unwrap();
        reservation.expr_hash = cc1h_snapshot.expr_hash.clone();
        reservation.billing_snapshot_json =
            serde_json::to_string(&BTreeMap::from([("default".to_string(), cc1h_snapshot)]))
                .unwrap();
        let error = relay_container_provider_usage_final_quota(
            &relay_container_test_provider_usage_payload(),
            &reservation,
            None,
        )
        .expect_err("OpenAI-semantic cc1h settlement must fail closed");
        assert!(error
            .to_string()
            .contains("requires Anthropic usage semantics"));

        let nonfinite_snapshot =
            cinatoken_billing::estimate_tiered_billing_snapshot_with_request_at(
                "gpt-test",
                r#"tier("default", p / (c - 500))"#,
                cinatoken_billing::TokenParams {
                    p: 100.0,
                    c: 501.0,
                    ..cinatoken_billing::TokenParams::default()
                },
                1.0,
                cinatoken_billing::RequestInput::default(),
                1_700_000_000,
            )
            .unwrap();
        reservation.expr_hash = nonfinite_snapshot.expr_hash.clone();
        reservation.billing_snapshot_json = serde_json::to_string(&BTreeMap::from([(
            "default".to_string(),
            nonfinite_snapshot,
        )]))
        .unwrap();
        let error = relay_container_provider_usage_final_quota(
            &relay_container_test_provider_usage_payload(),
            &reservation,
            None,
        )
        .expect_err("non-finite tiered quota must fail closed");
        assert!(error.to_string().contains("produced an invalid quota"));
    }

    #[test]
    fn relay_container_provider_usage_derives_flat_total_and_requires_priced_fields() {
        let mut snapshot = cinatoken_billing::FlatPricingSnapshot::from_config(
            "gpt-test",
            "default",
            &cinatoken_billing::PricingConfig::new(),
            1.0,
            0,
        );
        snapshot.mode = cinatoken_billing::FlatBillingMode::PerToken;
        snapshot.model_price = None;
        snapshot.model_ratio = 1.0;
        snapshot.completion_ratio = 1.0;
        snapshot.group_ratio = 1.0;
        snapshot.cache_ratio = 1.0;
        snapshot.cache_creation_ratio = 1.0;
        snapshot.cache_creation_ratio_5m = 1.0;
        snapshot.cache_creation_ratio_1h = 1.0;
        snapshot.image_ratio = 1.0;
        snapshot.audio_ratio = 1.0;
        snapshot.audio_completion_ratio = 1.0;
        snapshot.uses_audio_detail_billing = false;
        snapshot.audio_input_price_per_million = 0.0;

        let mut reservation = relay_billing_test_reservation("reserved");
        reservation.billing_kind = "flat".to_string();
        reservation.model_name = "gpt-test".to_string();
        reservation.selected_group = "default".to_string();
        reservation.billing_snapshot_json = serde_json::to_string(&BTreeMap::from([(
            "default".to_string(),
            BTreeMap::from([("1".to_string(), snapshot.clone())]),
        )]))
        .unwrap();

        let mut payload = relay_container_test_provider_usage_payload();
        payload.reported_usage_fields =
            RELAY_CONTAINER_USAGE_PROMPT_REPORTED | RELAY_CONTAINER_USAGE_COMPLETION_REPORTED;
        payload.total_tokens = 0;
        assert_eq!(
            relay_container_provider_usage_final_quota(&payload, &reservation, Some("1")).unwrap(),
            1_500
        );

        snapshot.cache_ratio = 0.5;
        reservation.billing_snapshot_json = serde_json::to_string(&BTreeMap::from([(
            "default".to_string(),
            BTreeMap::from([("1".to_string(), snapshot.clone())]),
        )]))
        .unwrap();
        assert!(
            relay_container_provider_usage_final_quota(&payload, &reservation, Some("1")).is_err()
        );
        payload.reported_usage_fields |= RELAY_CONTAINER_USAGE_CACHED_REPORTED;
        assert_eq!(
            relay_container_provider_usage_final_quota(&payload, &reservation, Some("1")).unwrap(),
            1_500
        );

        snapshot.cache_ratio = 1.0;
        snapshot.model_ratio = f64::MAX;
        reservation.billing_snapshot_json = serde_json::to_string(&BTreeMap::from([(
            "default".to_string(),
            BTreeMap::from([("1".to_string(), snapshot)]),
        )]))
        .unwrap();
        let error = relay_container_provider_usage_final_quota(&payload, &reservation, Some("1"))
            .expect_err("overflowed flat quota must fail closed");
        assert!(error.to_string().contains("produced an invalid quota"));
    }

    #[test]
    fn relay_container_financial_refund_handles_tokenless_request_policy() {
        let headers = "{\"cache-control\":\"no-store\",\"content-type\":\"application/json\",\"x-request-id\":\"request-001\"}";
        let headers_sha256 = relay_container_sha256_hex(headers.as_bytes());
        let response_key = concat!(
            "container-client-responses/v1/relayreserve-test/2/",
            "9999999999999999999999999999999999999999999999999999999999999999"
        );
        let response = relay_container_test_client_response(503, &headers_sha256, response_key);
        let audit_payload = "{\"action\":\"container_refund\"}";
        let audit_sha256 = relay_container_sha256_hex(audit_payload.as_bytes());
        let mut operation = relay_container_test_operation();
        operation.status = "dispatched".to_string();
        let mut reservation = relay_billing_test_reservation("reserved");
        reservation.token_id = 0;
        reservation.pre_consumed_quota = 75;
        reservation.final_quota = 0;
        reservation.finalization_reason.clear();
        reservation.request_accounted = 0;
        reservation.lease_expires_at = operation.owner_lease_expires_at;

        for request_accounting in [
            RelayBillingRequestAccounting::Skip,
            RelayBillingRequestAccounting::Account,
        ] {
            let command = RelayContainerFinancialTerminalCommand {
                reservation_key: &operation.reservation_key,
                operation_id: &operation.operation_id,
                operation_owner_generation: operation.owner_generation,
                expected_operation_status: RelayContainerOperationExpectedStatus::Dispatched,
                admission_sha256: &operation.admission_sha256,
                billing_owner_generation: reservation.owner_generation,
                terminal: RelayContainerOperationTerminalRecord::Failed {
                    response_status: 422,
                    response_code: "provider_http_error",
                },
                action: RelayContainerFinancialTerminalAction::Refund {
                    finalization_reason: "provider_http_error",
                    request_accounting,
                },
                client_response: Some(response),
                provider_response: Some(relay_container_test_provider_response(
                    "interpreted_reject",
                    "http_error",
                    503,
                    503,
                    Some("provider_http_error"),
                    response,
                )),
                audit_payload_json: audit_payload,
                audit_payload_sha256: &audit_sha256,
                scheduled_terminalization: None,
                committed_at: 150,
            };
            let prepared =
                prepare_relay_container_financial_terminal(&command, &operation, &reservation);
            if request_accounting == RelayBillingRequestAccounting::Account {
                assert!(prepared.is_err());
                continue;
            }
            let prepared = prepared.unwrap();
            assert_eq!(prepared.billing_action, "refund");
            assert_eq!(prepared.billing_final_quota, None);
            assert_eq!(prepared.user_quota_delta, 75);
            assert_eq!(prepared.token_quota_delta, 0);
            assert_eq!(prepared.request_count_delta, 0);
            assert_eq!(prepared.billing_request_accounted, 0);
            assert_eq!(prepared.event_client_response_status, Some(422));
            assert_eq!(prepared.client_replay_status, Some(503));
        }
    }

